      if (typeof o.onSubmit === 'function') { const sub = o.onSubmit; o.onSubmit = async function (ff) { const res = await sub.apply(this, arguments); if (res !== false) { try { const all = ld(FK); const m = all[key] = all[key] || {}; ff.querySelectorAll('select[name], input[name][type=text], input[name]:not([type])').forEach(el => { if (SKIPF.has(el.name) || !el.value || el.value.length > 40) return; const h = m[el.name] = m[el.name] || {}; h[el.value] = (h[el.value] || 0) + 1; const ks = Object.keys(h); if (ks.length > 6) delete h[ks.sort((a, b) => h[a] - h[b])[0]]; }); const keys = Object.keys(all); if (keys.length > 40) delete all[keys[0]]; sv(FK, all); } catch (e) { /* */ } } return res; }; }
