  const inboxBox = () => { const xs = inbox(); if (!xs.length) return ''; return `<div class="bx" style="border-color:var(--kb)"><h3>${esc(isCeo() ? L('مستني منك', 'Waiting for you') : L('رجعلك من د. طارق', 'Back from Dr. Tarek'))} <span class="pl a" style="margin:0">${xs.length}</span></h3>${xs.map(x => { const rec = x.kind === 'agr' ? x.d.agreement : (x.d.offers || []).find(o => o.v === x.v); const doc = x.kind === 'agr' ? rec.doc : docOf(rec); return `<div class="of"><b>${esc(title(x.d.id))}</b><span>${esc(x.kind === 'agr' ? L('العقد', 'Agreement') : L('أوفر', 'Offer') + ' V' + x.v)}</span>${x.s === 'fyi' ? `<span class="pl" style="margin:0">${esc(L('للاطلاع', 'For your information'))}</span>` : apPill(rec, doc)}${rec.approval && rec.approval.note && x.s === 'changes' ? `<span class="muted">«${esc(rec.approval.note)}»</span>` : ''}<span class="grow"></span>${btn(`gopen:${x.kind}|${x.d.id}|${x.v || ''}`, L('افتح', 'Open'), 'pb')}</div>`; }).join('')}</div>`; };

